import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'

export default defineConfig({ base: './', plugins: [vue()] })

import { createRouter, createWebHashHistory } from 'vue-router'
import ProductListView from '../views/ProductListView.vue'
import ProductDetailView from '../views/ProductDetailView.vue'

export default createRouter({
  history: createWebHashHistory(),
  routes: [
    { path: '/', component: ProductListView },
    { path: '/product/:id', component: ProductDetailView }
  ]
})

:root { font-family: 'Noto Serif SC', Georgia, serif; color: #352f29; background: #f8f5ef; }
* { box-sizing: border-box; }
body { margin: 0; }
a { color: inherit; text-decoration: none; }
header { height: 76px; display: flex; align-items: center; gap: 42px; padding: 0 max(24px, calc((100% - 1120px) / 2)); background: #f8f5ef; border-bottom: 1px solid #ded6ca; }
.brand { font-size: 22px; font-weight: 800; margin-right: auto; }
nav { display: flex; gap: 24px; }
main { width: min(1120px, calc(100% - 40px)); margin: 0 auto; }
.hero { margin-top: 36px; min-height: 330px; padding: 70px; border-radius: 4px; background: linear-gradient(100deg, #314237, #71826f); color: #fff; }
.hero h1 { font-size: clamp(2.4rem, 5vw, 4.2rem); margin: 14px 0; }
.hero p { max-width: 520px; line-height: 1.8; color: #e7eee8; }
.toolbar { display: flex; justify-content: space-between; align-items: center; margin: 52px 0 22px; }
.grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; padding-bottom: 70px; }
.cover { aspect-ratio: 1; display: grid; place-items: center; font-size: 90px; margin-bottom: 16px; }
.product small { color: #887b6b; }
.product h3 { margin: 7px 0; }
.detail { display: grid; grid-template-columns: 1.15fr 1fr; gap: 64px; padding-top: 70px; align-items: center; }
.detail-cover { aspect-ratio: 1; display: grid; place-items: center; font-size: 150px; background: #d9c8ae; }
.detail h1 { font-size: 48px; margin: 10px 0; }
.detail p { line-height: 1.9; color: #6f655a; margin: 22px 0; }
.price { display: block; font-size: 25px; }
.detail .el-button { margin-left: 14px; }
@media (max-width: 760px) { nav { display: none; } .hero { padding: 42px 28px; } .grid, .detail { grid-template-columns: 1fr; } }
